import 'package:flutter/material.dart';
import 'dart:async';
void main()=>runApp(const ToofanApp());
class ToofanApp extends StatelessWidget{const ToofanApp({super.key});@override Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,theme:ThemeData.dark().copyWith(scaffoldBackgroundColor:Color(0xFF0A1931)),home:const Splash());}
class Splash extends StatefulWidget{const Splash({super.key});@override State<Splash> createState()=>_S();}
class _S extends State<Splash>{@override void initState(){super.initState();Timer(Duration(seconds:2),()=>Navigator.pushReplacement(context,MaterialPageRoute(builder:(_)=>MainScreen())));} @override Widget build(BuildContext c)=>Scaffold(body:Container(decoration:BoxDecoration(gradient:LinearGradient(colors:[Color(0xFF0A1931),Color(0xFF1E3A5F)])),child:Center(child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[Icon(Icons.bolt,size:100,color:Color(0xFF00D4FF)),Text('TOOFAN',style:TextStyle(fontSize:48,fontWeight:FontWeight.bold)),Text('Connect • Communicate • Protect')]))));}
class MainScreen extends StatefulWidget{const MainScreen({super.key});@override State<MainScreen> createState()=>_M();}
class _M extends State<MainScreen>{int i=0;@override Widget build(BuildContext c){final p=[ListView(children:[SizedBox(height:80,child:ListView(scrollDirection:Axis.horizontal,children:[Chip(label:Text('Your Story')),Chip(label:Text('Aisha')),Chip(label:Text('Leo'))])),Card(child:ListTile(title:Text("What's happening?"))),Card(color:Colors.white10,child:ListTile(leading:CircleAvatar(child:Text('SK')),title:Text('Sara Khan'),subtitle:Text('Life is better with good people ❤️ #toofan')))]),Center(child:Text('5. VIDEO\nTikTok Full Screen\n1.2K Likes')),Center(child:Text('6. EXPLORE\n#LifeStyle 1.2M\nSuggested People')),ListView(padding:EdgeInsets.all(10),children:[Container(color:Colors.red,padding:EdgeInsets.all(10),child:Text('Safety Alert!')),ListTile(title:Text('Family: 128 Active')),ElevatedButton(onPressed:(){},child:Text('Emergency Alert'))]),ListView(children:[ListTile(title:Text('Profile - Sara Khan'),subtitle:Text('243 Posts')),ListTile(title:Text('13. Settings')),ListTile(title:Text('14. Hijab Settings'),trailing:Switch(value:true,onChanged:(v){})),ListTile(title:Text('20-23. Admin Panel'))])];return Scaffold(appBar:AppBar(title:Text('TOOFAN'),backgroundColor:Color(0xFF0A1931)),body:p[i],bottomNavigationBar:BottomNavigationBar(currentIndex:i,onTap:(v)=>setState(()=>i=v),type:BottomNavigationBarType.fixed,backgroundColor:Color(0xFF0A1931),items:[BottomNavigationBarItem(icon:Icon(Icons.home),label:'Home'),BottomNavigationBarItem(icon:Icon(Icons.video_library),label:'Video'),BottomNavigationBarItem(icon:Icon(Icons.explore),label:'Explore'),BottomNavigationBarItem(icon:Icon(Icons.family_restroom),label:'Family'),BottomNavigationBarItem(icon:Icon(Icons.person),label:'Profile')]));}}
